import{_ as e,o as r,c as o,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph Orchestrator Meeting 2022-05-17","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2022-05-17","date":"2022-05-17T00:00:00.000Z","updated":"2022-05-26T00:00:00.000Z","tags":["Ceph","Rook","NFS","OpenStack","Distributed Storage","CRUSH Algorithm","High Availability","Kubernetes","Docker","Cloud Computing"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-05-17.md","filePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-05-17.md","lastUpdated":1780460162000}'),l={name:"posts/2022/Ceph_Orchestrator_Meeting_2022-05-17.md"};function a(s,t,n,p,c,_){return r(),o("div",null,[...t[0]||(t[0]=[i("<p>会议纪要：</p><p><strong>主题</strong>： 讨论Ceph Rook与NFS操作的兼容性问题及后续行动计划</p><p><strong>问题描述</strong>：</p><ul><li>当Rook Orchestrator模块启用时，NFS操作失败。John Mulligan的工作允许NFS CLI在没有Orchestrator模块的情况下工作，但在启用了Orchestrator模块后，NFS命令将失败。</li><li>在Pacific版本中，无论是否启用Orchestrator模块，NFS均可正常工作。但在Quincy版本中，只有在Orchestrator模块未启用时才能正常工作。</li><li>问题可能源于Quincy版本的回退（backport）未能完全实现，导致部分逻辑或异常处理代码缺失。</li></ul><p><strong>讨论内容</strong>：</p><ul><li>提出可能的解决方案，包括从模块中移除某些逻辑并引发合适的异常，或者尝试修复问题。</li><li>确认问题可能与Rook模块相关，需要检查该模块在Pacific和Quincy两个版本中的差异。</li><li>讨论OpenStack使用情况下对稳定虚拟IP的需求，以及可能的解决方案。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>检查并确认Rook NFS的回退情况，确保没有遗漏。</li><li>验证不同版本的Rook模块中是否存在差异，特别是与NFS操作相关的代码块。</li><li>考虑OpenStack环境下对NFS服务器的要求，评估是否需要采取特殊措施来处理客户端IP限制的情况。</li><li>确定OpenStack发布时间线，以便相应地调整项目的优先级和计划。</li></ul><p><strong>其他事项</strong>：</p><ul><li>讨论了功能请求，涉及为Ganesha提供非HA Proxy解决方案以提供稳定的虚拟IPs。</li><li>强调了对OpenStack发布时间的了解对于项目计划的重要性。</li></ul><p><strong>会议结论</strong>：</p><ul><li>团队需要调查和解决Rook NFS操作中存在的问题，同时考虑OpenStack环境中的特殊需求。</li><li>下一步行动包括检查代码差异、验证回退情况，并与OpenStack团队合作明确时间线和需求。</li><li>下一次会议将在一周后举行，届时将继续讨论这些问题和进展。</li></ul>",12)])])}const u=e(l,[["render",a]]);export{h as __pageData,u as default};
